class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, a, b):
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return
        if self.size[ra] < self.size[rb]:
            ra, rb = rb, ra          # make ra the bigger root
        self.parent[rb] = ra
        self.size[ra] += self.size[rb]


uf = UnionFind(8)
largest = 1
for a, b in [(0, 1), (2, 3), (1, 3), (4, 5), (5, 0), (6, 7)]:
    uf.union(a, b)
    size = uf.size[uf.find(a)]
    largest = max(largest, size)
    print(f"join {a}-{b}: group of {size}, largest {largest}")
print("Parents:", uf.parent)

