class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n
        self.count = n               # the number of groups

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, a, b):
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return False             # already joined: this edge closes a cycle
        if self.size[ra] < self.size[rb]:
            ra, rb = rb, ra
        self.parent[rb] = ra
        self.size[ra] += self.size[rb]
        self.count -= 1
        return True


n = 6
uf = UnionFind(n)
for a, b in [(0, 1), (1, 2), (3, 4), (2, 0), (4, 5), (5, 3)]:
    if uf.union(a, b):
        print(f"{a}-{b}: joins, {uf.count} networks")
    else:
        print(f"{a}-{b}: redundant")
print("Networks:", uf.count)

